import numpy as np, sys, itertools
from scipy.spatial import ConvexHull, HalfspaceIntersection
from bprop import hull_halfspaces, cube_halfspaces, vol_hs, scaled_halfspaces, cube_vertices

def rot(theta, axis):
    axis = np.asarray(axis, float); axis /= np.linalg.norm(axis)
    K = np.array([[0, -axis[2], axis[1]], [axis[2], 0, -axis[0]], [-axis[1], axis[0], 0]])
    return np.eye(3) + np.sin(theta) * K + (1 - np.cos(theta)) * K @ K

def rotate_hs(hs, R):  # R K = {x : a.(R^T x) + c <= 0} => normal R a
    return np.hstack([hs[:, :-1] @ R.T, hs[:, -1:]])

def body_inter_cubes(theta, axis, half2=(1,1,1)):
    C = cube_halfspaces(3)
    B = hull_halfspaces(cube_vertices(3, half2))
    return np.vstack([C, rotate_hs(B, rot(theta, axis))])

def body_hull_cubes(theta, axis, half2=(1,1,1)):
    V = np.vstack([cube_vertices(3), cube_vertices(3, half2) @ rot(theta, axis).T])
    return hull_halfspaces(V)

def body_cube_slab(v, w):
    v = np.asarray(v, float); v /= np.linalg.norm(v)
    return np.vstack([cube_halfspaces(3), np.append(v, -w), np.append(-v, -w)])

def logV(hsK, t, s):
    return np.log(vol_hs(np.vstack([scaled_halfspaces(hsK, t**s), cube_halfspaces(3)]), 3))

def max_second_deriv(hsK, t, s_lo=-4, s_hi=4, N=801):
    s = np.linspace(s_lo, s_hi, N); h = s[1] - s[0]
    g = np.array([logV(hsK, t, x) for x in s])
    d2 = (g[:-2] - 2 * g[1:-1] + g[2:]) / h**2
    i = d2.argmax()
    # refine near argmax
    s2 = np.linspace(s[i], s[i + 2], 41); h2 = s2[1] - s2[0]
    g2 = np.array([logV(hsK, t, x) for x in s2])
    d22 = (g2[:-2] - 2 * g2[1:-1] + g2[2:]) / h2**2
    return d2.max(), s[i + 1], d22.max()

if __name__ == "__main__":
    rng = np.random.default_rng(1)
    ts = [np.array(x, float) for x in [(1, 1, 2), (1, 2, 4), (2, 3, 5), (2, 2, 2), (0.5, 1, 3), (1, 1.1, 1.2)]]
    ts += [np.exp(rng.uniform(-1.5, 1.5, 3)) for _ in range(4)]
    axes = [(0, 0, 1), (1, 1, 1), (1, 2, 3), (0.3, -0.7, 1.1)]
    worst = -np.inf
    for name, mk in [("inter", body_inter_cubes), ("hull", body_hull_cubes)]:
        for axis in axes:
            for theta in [0.05, 0.15, 0.3, 0.6, np.pi / 4]:
                for half2 in [(1, 1, 1), (0.7, 1.0, 1.3), (1.2, 1.2, 0.5)]:
                    hsK = mk(theta, axis, half2)
                    for t in ts:
                        m, s0, m2 = max_second_deriv(hsK, t)
                        worst = max(worst, m2)
                        if m2 > 1e-7:
                            print(f"POSITIVE? {name} axis={axis} theta={theta:.3f} half2={half2} t={np.round(t,3)} d2max={m:.3e} at s={s0:.2f}, refined {m2:.3e}")
        print(f"done {name}; worst so far {worst:.3e}", flush=True)
    for v in [(1, 2, 3), (1, 1, 0.1), (0.2, 1, 1.5), (1, 0, 0.3)]:
        for w in [0.3, 0.6, 1.0, 1.4]:
            hsK = body_cube_slab(v, w)
            for t in ts:
                m, s0, m2 = max_second_deriv(hsK, t)
                worst = max(worst, m2)
                if m2 > 1e-7:
                    print(f"POSITIVE? slab v={v} w={w} t={np.round(t,3)} d2max={m:.3e} at s={s0:.2f}, refined {m2:.3e}")
    print("WORST (log V)'' estimate =", worst)
