import numpy as np, sys, json, time
from scipy.optimize import minimize
sys.path.insert(0, '/app/scratch')
from poincare_n import c_constant_n, normalize, polytope_data_n

def unpack(x, m, n):
    return normalize(x[:n * m].reshape(m, n)), np.exp(x[n * m:])

def objective(x, m, n, min_frac):
    if np.abs(x[n * m:]).max() > 4.0: return 1e3
    U, h = unpack(x, m, n)
    try:
        c, d = c_constant_n(U, h, return_data=True)
    except Exception:
        return 1e3
    if not np.isfinite(c): return 1e3
    pen = 0.0
    if min_frac > 0:   # keep every facet pair present with a minimal area fraction (stay away from trivial degenerations)
        A = d["A"]; mm = len(A) // 2
        frac = A[:mm] / max(A.sum(), 1e-300)
        pen = 1e2 * np.clip(min_frac - frac, 0, None).sum()
    return c + pen

def start(mode, m, n, rng):
    if mode == "random":
        U0 = rng.standard_normal((m, n)); g0 = rng.uniform(-0.3, 0.3, m)
    elif mode == "nearbox":
        U0 = np.vstack([np.eye(n) + 0.05 * rng.standard_normal((n, n)), rng.standard_normal((m - n, n))])
        Un = normalize(U0); g0 = np.concatenate([np.zeros(n), np.log(np.abs(Un[n:]).sum(axis=1) * rng.uniform(0.6, 0.98, m - n))])
    elif mode == "nearprod":
        n1 = rng.integers(2, n - 1); n2 = n - n1
        m1 = rng.integers(n1 + 1, n1 + 3); m2 = m - m1
        if m2 < n2 + 1: m2 = n2 + 1; m1 = m - m2
        U0 = np.zeros((m, n)); U0[:m1, :n1] = rng.standard_normal((m1, n1)); U0[m1:, n1:] = rng.standard_normal((m2, n2))
        U0 += 10**rng.uniform(-2.5, -0.7) * rng.standard_normal(U0.shape); g0 = rng.uniform(-0.2, 0.2, m)
    elif mode == "cubeslabs":
        U0 = np.vstack([np.eye(n), rng.standard_normal((m - n, n))]); Un = normalize(U0)
        g0 = np.concatenate([np.zeros(n), np.log(np.abs(Un[n:]).sum(axis=1) * rng.uniform(0.3, 0.95, m - n))])
    return np.concatenate([U0.ravel(), g0])

if __name__ == "__main__":
    n, m, seed, restarts, mode = int(sys.argv[1]), int(sys.argv[2]), int(sys.argv[3]), int(sys.argv[4]), sys.argv[5]
    min_frac = float(sys.argv[6]) if len(sys.argv) > 6 else 0.0
    rng = np.random.default_rng(seed); out = open(f"opt_logs/cn_{mode}_n{n}_m{m}_s{seed}.jsonl", "a"); best = np.inf
    for r in range(restarts):
        x0 = start(mode, m, n, rng); t0 = time.time()
        c0 = objective(x0, m, n, min_frac)
        res = minimize(objective, x0, args=(m, n, min_frac), method="Nelder-Mead",
                       options={"maxfev": 2500, "xatol": 1e-6, "fatol": 1e-9, "adaptive": True})
        U, h = unpack(res.x, m, n)
        try: c_final = c_constant_n(U, h)
        except Exception: c_final = float("nan")
        rec = {"n": n, "m": m, "mode": mode, "seed": seed, "r": r, "c0": float(c0), "c_obj": float(res.fun), "c": float(c_final),
               "U": U.tolist(), "h": h.tolist(), "secs": time.time() - t0}
        out.write(json.dumps(rec) + "\n"); out.flush()
        if np.isfinite(c_final) and c_final < best:
            best = c_final; print(f"r={r} {mode}: c0={c0:.5f} -> c={c_final:.8f} (n^2={n*n}) [{time.time()-t0:.0f}s]", flush=True)
    print("BEST", best)
