import numpy as np, sys, json, itertools
from scipy.spatial import ConvexHull, HalfspaceIntersection
from bprop import random_rotation
def hs_of_verts(V): return ConvexHull(V).equations          # a.x + c <= 0
def cube_hs(n):
    return np.array([np.append(s * np.eye(n)[i], -1.0) for i in range(n) for s in (1, -1)])
def vol(hs, n):
    hi = HalfspaceIntersection(hs, np.zeros(n)); return ConvexHull(hi.intersections).volume
def scaled(hs, d): return np.hstack([hs[:, :-1] / d, hs[:, -1:]])    # D K where D = diag(d)
def logV(hsK, t, s, n): return np.log(vol(np.vstack([scaled(hsK, t ** s), cube_hs(n)]), n))
def maxd2(hsK, t, n, s_lo=-3, s_hi=3, N=241):
    s = np.linspace(s_lo, s_hi, N); h = s[1] - s[0]
    g = np.array([logV(hsK, t, x, n) for x in s]); d2 = (g[:-2] - 2 * g[1:-1] + g[2:]) / h ** 2
    i = d2.argmax(); s2 = np.linspace(s[i], s[i + 2], 21); h2 = s2[1] - s2[0]
    g2 = np.array([logV(hsK, t, x, n) for x in s2]); d22 = (g2[:-2] - 2 * g2[1:-1] + g2[2:]) / h2 ** 2
    # midpoint (exact) check at the flagged location
    return d2.max(), s[i + 1], d22.max()
if __name__ == "__main__":
    n = int(sys.argv[1]); seed = int(sys.argv[2]); rng = np.random.default_rng(seed); worst = -np.inf
