    for trial in range(12):
        R = random_rotation(rng, n); t = np.exp(rng.uniform(-1.2, 1.2, n))
        bodies = [("rot cube", cube_v @ R.T), ("rot box", (cube_v * np.exp(rng.uniform(-0.7, 0.7, n))) @ R.T),
                  ("rot cross", 1.6 * cross_v @ R.T), ("rot cross-box", (cross_v * np.exp(rng.uniform(-0.5, 0.9, n))) @ R.T)]
        P = rng.standard_normal((rng.integers(n + 1, 3 * n), n)); bodies.append(("random sym poly", np.vstack([P, -P])))
        for name, V in bodies:
            m, s0, m2 = maxd2(hs_of_verts(V), t, n); worst = max(worst, m2)
            print(f"trial {trial} {name}: max (log V)'' ≈ {m:+.3e} at s={s0:.2f}, refined {m2:+.3e}" + ("  <-- POSITIVE?" if m2 > 1e-6 else ""), flush=True)
    print("WORST second derivative estimate:", worst)
